			printf("数字太小了\n");
		else if (c-k>0 && c-k<50)
			printf("数字小了一丢丢\n");
		else if (k-c>=50)
			printf("数字太大了\n");
		else if (k-c>0 && k-c<50)
			printf("数字大了一丢丢\n");
		else
			printf("脑子是个好东西，你终于猜对了\n");
	}
	while(c!=k);
}

