#include &quot;stdafx.h&quot;
#include&lt;math.h&gt;
#include&lt;time.h&gt;
#include&lt;stdlib.h&gt;

int _tmain(int argc, _TCHAR* argv[])
{
	int a,i;
	srand(time(NULL));
	a=rand()%100+1;//产生一个随机数
	printf(&quot;请输入一个1至100之间的整数:\n&quot;);
	scanf(&quot;%d&quot;,&amp;i);
	for(;i!=a;)
	{
		if(i&gt;=1&amp;&amp;i&lt;=100)//当输入数字1~100之间才执行下一步
		{
		if((i-a)&gt;0&amp;&amp;(i-a)&lt;10)
		{
			printf(&quot;数字大了。\n&quot;);
		}
		else***if((i-a)&gt;=10)
		{
			printf(&quot;数字大太多了！\n&quot;);
		}
		else***if((i-a)&lt;0&amp;&amp;(i-a)&gt;-10)
		{
			printf(&quot;数字小了。\n&quot;);
		}
		else***if((i-a)&lt;=-10)
		{
			printf(&quot;数字小太多了！\n&quot;);
		}
			printf(&quot;请再输入一个1至100之间的整数:\n&quot;);
			scanf(&quot;%d&quot;,&amp;i);
		}
		else
			printf(&quot;输入不符合规定，请再输入一个1至100之间的整数:\n&quot;);
			scanf(&quot;%d&quot;,&amp;i);
	}
	printf(&quot;恭喜你答对了！\n&quot;);
	return 0; 
}

